ALTER TABLE public.lead_events DROP CONSTRAINT IF EXISTS lead_events_event_check;
ALTER TABLE public.lead_events ADD CONSTRAINT lead_events_event_check CHECK (event = ANY (ARRAY['page_view','cta_click','form_start','form_submit','booking_start','booking_complete','chat_opened','role_selected','qualification_started','lead_submitted','hot_lead_created','booking_clicked','traveller_registration_clicked','whatsapp_clicked','lead_converted_to_booking']));